const body = $json.body ?? $json;
const stages = ['order','supplier_sourcing','quotation','sampling','customer_approval','production','fulfillment'];
const types = ['order_created','stage_entered','stage_exited','order_cancelled'];
const issues = [];
for (const key of ['event_id','order_id','stage','event_type','event_timestamp','source']) if (!body[key]) issues.push(`missing:${key}`);
if (!stages.includes(body.stage)) issues.push('invalid_stage');
if (!types.includes(body.event_type)) issues.push('invalid_event_type');
const parsed = Date.parse(body.event_timestamp);
if (Number.isNaN(parsed)) issues.push('invalid_timestamp');
const canonical = JSON.stringify(body, Object.keys(body).sort());
let hash = 2166136261;
for (let i = 0; i < canonical.length; i++) hash = Math.imul(hash ^ canonical.charCodeAt(i), 16777619);
const event = {...body, event_timestamp: Number.isNaN(parsed) ? body.event_timestamp : new Date(parsed).toISOString(), payload_hash: body.payload_hash ?? (hash >>> 0).toString(16)};
const accepted = issues.length === 0;
const store = $getWorkflowStaticData('global');
store.events = store.events ?? [];
let response;
if (accepted) {
  const duplicate = store.events.some((row) => row.event_id === event.event_id && row.payload_hash === event.payload_hash);
  const row = {event_id:event.event_id, order_id:event.order_id, stage:event.stage, event_type:event.event_type, event_timestamp:event.event_timestamp, payload_hash:event.payload_hash, duplicate_delivery:duplicate, captured_at:new Date().toISOString()};
  store.events.push(row);
  response = {accepted:true, storage:'local_mock', duplicate_delivery:duplicate, event_id:event.event_id, captured_events:store.events.length, row};
} else {
  response = {accepted:false, storage:'local_mock', issues, event_id:event.event_id ?? null};
}
return [{json:{...response, http_status: accepted ? 200 : 400}}];
